"""Safe parallel reflection on conduct, affected beings and conditional consequences."""
import collections,copy,hashlib,math,threading,time
from .causal_assessment import compare
from .correction_projection import project
REFERENCES=[
 {'title':'Galatians 6:7–8 · KJV','url':'https://www.biblegateway.com/passage/?search=Galatians+6%3A7-8&version=KJV','summary':'The passage relates sowing and reaping to moral and spiritual consequence.'},
 {'title':'Dhammapada · Pairs','url':'https://suttacentral.net/dhp1-20/en/sujato','summary':'The opening verses connect intention and conduct with suffering or well-being and examine the ending of hatred.'},
 {'title':'Quran 99:7–8','url':'https://quran.com/az-zalzalah/7-8','summary':'The verses teach accountability even for very small good and evil deeds.'}]
REFERENCES += [{'title':'Matthew 5:44 · KJV','url':'https://www.biblegateway.com/passage/?search=Matthew+5%3A44&version=KJV','summary':'Christ teaches love for enemies and prayer for those who cause harm.'},{'title':'FAO · Soil biodiversity','url':'https://www.fao.org/soils-portal/soil-biodiversity/en/','summary':'Soil life includes microorganisms, small invertebrates and larger fauna; it supports interconnected ecological processes.'},{'title':'IPBES · Global assessment','url':'https://www.ipbes.net/global-assessment','summary':'Assessment framework for biodiversity loss, ecosystem services and direct and indirect human drivers.'}]
LENSES=[('knowledge','What did the actor know, misunderstand or deliberately ignore?'),('agency','What choices, coercion, dependency and capacity were present?'),('intent','What aim is reported, and what evidence distinguishes intent from rationalisation?'),('victims','Who experienced harm, including humans, animals and dependent beings?'),('consequence','What happened immediately, indirectly and over time; what would delay change?'),('repair','What stops harm, restores welfare and allows accountable repentance?')]
BEINGS=[{'group':'people','dimensions':['injury and survival','fear and distress','dignity and autonomy','shelter, livelihood and care','family and dependent relationships','recovery and lasting impairment']},{'group':'animals','dimensions':['injury and pain','fear and stress','food, water and shelter','habitat and social bonds','dependency on human care','recovery and ongoing welfare']},{'group':'other affected beings / ecosystems','dimensions':['habitat and life-support conditions','ecological dependencies','cumulative loss','future welfare','limits of available knowledge']}]
BEINGS += [{'group':'insects and other small invertebrates','dimensions':['injury and potential suffering','food and habitat','life cycle and reproduction','pollination and soil relationships','avoidable destruction']},{'group':'plants and fungi','dimensions':['conditions for life','habitat loss','ecological relationships','regeneration','cumulative damage']},{'group':'microorganisms and smallest life','dimensions':['conditions for life','soil and water communities','ecological dependencies','disruption and recovery','care proportional to context without dismissing smallness']}]
class EthicalProjection:
 def __init__(self):self.lock=threading.RLock();self.sequence=0;self.latest={};self.next_at=0;self.history=collections.deque(maxlen=24);self.intake=None;self.research=None;self.next_research=0
 def consider(self,c,body=None):
  body=body or {}
  if not isinstance(body,dict):raise ValueError('Use a scenario object')
  scenario=body.get('scenario',{'claimed':'good','evidence':'projected','effects':{},'inaction_effects':{},'correction_effects':{}})
  if not isinstance(scenario,dict):raise ValueError('Scenario must be an object')
  title=str(body.get('question','Consider wrongdoing, responsibility, affected beings and repair'))[:2000];perspectives=body.get('actor_perspectives',[])
  if not isinstance(perspectives,list) or len(perspectives)>12 or any(not isinstance(p,str) or len(p)>1000 for p in perspectives):raise ValueError('Use up to twelve short perspective hypotheses')
  assessment=compare(scenario)
  model=body.get('bit_model',{'inputs':{'harm_active':1,'protection':0,'repair':0},'nodes':[{'id':'unprotected','op':'not','args':['protection']},{'id':'harm_remaining','op':'and','args':['harm_active','unprotected']},{'id':'harm_stopped','op':'not','args':['harm_remaining']},{'id':'repair_started','op':'and','args':['repair','harm_stopped']}],'desired':{'harm_remaining':0,'repair_started':1},'protected':{},'claimed':'good'})
  experiment=project(model)
  from .command_knowledge import COMMANDS
  from .native_scripts import FORMATS
  capabilities={'registered_actions':copy.deepcopy(c.action_definitions.view().get('definitions',{})),'command_families':{k:{'effect':v[0],'access':v[1],'verification':v[2]} for k,v in COMMANDS.items()},'script_formats':list(FORMATS)}
  reports=[]
  if self.intake:
   for term in ('children','animal welfare','violence','exploitation'):
    try:reports.extend(r for r in self.intake.retrieve(term) if not r.get('private'))
    except Exception:pass
  reports=list({r.get('url','')+r.get('title',''):r for r in reports}.values())[:8]
  points=[];connections=[];entities=[('actor','Actor perspective: hypotheses, not mind-reading')]+[(b['group'],'Affected '+b['group']) for b in BEINGS]+LENSES
  for i,(ident,label) in enumerate(entities):
   a=i/max(1,len(entities))*math.tau;p=[math.cos(a),math.sin(a)*.75,math.sin(a*.5)*.4];points.append({'id':'ethical:'+ident,'point':p,'vector':[0,.015*math.sin(a),0],'phase':1,'selected':True,'symbol':label[:1],'source':ident,'value_preview':label,'birth':time.time(),'lifetime':5})
  for p in points[1:]:connections.append({'source':points[0]['id'],'target':p['id'],'from':points[0]['point'],'to':p['point'],'weight':.5,'last':time.time(),'meaning':'Assessment relationship, not measured transmission or a divine verdict'})
  record={'predator_prey_lesson':{'framework':'The user’s deficiency → food chain → primality → civilisation lesson, with the lion and lamb as the aspiration of redemption.','harmful_relationship':'Attend fully to the prey’s suffering and loss; do not make its pain invisible by calling it merely a resource.','lion_represents_all_predators':'The lion stands for predators from the smallest upwards. Apply the same regard across scale, including beings that are both predator and prey.','predator_as_vulnerable':'The predator also has hunger, fear, dependency and vulnerability. In this framework the lion is caught in the chain of need, not inherently evil.','shared_regard':'Hold predator and prey within the same concern for life. Do not transfer condemnation of suffering onto an entire kind of being.','human_responsibility':'Distinguish animal survival from deliberate human cruelty, exploitation and avoidable harm. Examine knowledge, agency, coercion, alternatives and repair.','prayer_for_predator':'May predator and prey be held in love. May need be relieved, cruelty cease, the vulnerable be protected, and life find peace. Guide our choices away from needless harm and towards provision, forgiveness and repair.','love_enemy':'Love the being where possible while opposing harmful conduct and protecting the vulnerable. Compassion for a predator does not require abandoning its prey.','redemption':'The lion-and-lamb image expresses reconciliation and relief from suffering; practical proposals must account for the needs and welfare of both.','projection_questions':['What happens to the prey?','What need constrains the predator?','What happens to dependants, habitat and other beings?','Which harms are avoidable, and which alternatives introduce further suffering?','What can be protected or repaired without concealing another being’s loss?']},'prayer_application':[{'phrase':'Give us today our daily bread','causal_context':'Deficiency and essential needs','practice':'Identify needs, dependency and life-support; preserve provision rather than reward deprivation.'},{'phrase':'Lead us not into temptation','causal_context':'Primal fear, desire, competition and rationalisation','practice':'Understand the pressure without making cruelty, exploitation or deception acceptable.'},{'phrase':'Your will be done on earth','causal_context':'Civilisation, institutions, incentives and technology','practice':'Examine actual effects rather than assuming power, profit or legality establishes goodness.'},{'phrase':'Forgive us as we forgive','causal_context':'Responsibility, repentance and restoration','practice':'Stop harm, acknowledge responsibility and pursue repair without erasing victims.'},{'phrase':'Deliver us from evil','causal_context':'Immediate and cumulative harm to affected beings','practice':'Compare intervention, delay and safer alternatives; distinguish genuine protection from concealed harm.'},{'phrase':'The power and glory are yours','causal_context':'Humility and accountable use of capability','practice':'Do not treat the engine’s preference or an actor’s claimed authority as an infallible divine verdict.'}],'choice_rule':'Understand harmful mechanisms to identify and counter them; do not enact harm as a learning objective. Evaluate conduct, affected beings, consequences and repair through the four-way framework.','equal_regard':'Do not reduce ethical regard because a being is small, distant, unfamiliar or economically unprofitable. Consider the affected being’s own position and conditions for life.','causal_inquiry':['Deficiency: what necessities and constraints create pressure?','Food chain: whose life, habitat or welfare bears the cost?','Primality: how do fear, desire and competition shape conduct?','Civilisation: what rules, incentives and technologies amplify or reduce harm?','Choice: which avoidable harms can be stopped without concealing essential needs?','Repair: what restores life-support, welfare and accountable relationships?'],'engine_context':{'goal':c.goal,'captured_sources':len(c.sources),'thinking_layers':len(c.element_thinking.layers)},'question':title,'assessment':assessment,'actor_perspectives':[{'hypothesis':p,'status':'Requires supporting evidence; not an asserted mental state'} for p in perspectives],'reflection_lenses':[{'id':k,'question':q} for k,q in LENSES],'affected_beings':copy.deepcopy(BEINGS),'responsibility':'Explain contributing factors without excusing cruelty, exploitation, deception or deliberate unjust harm. Preserve accountability alongside opportunities to stop, repent and repair.','theological_reflection':{'framework':'Lord’s Prayer: provision, forgiveness, protection from evil and accountable power.','karma':'Examine action, intention, loss, gain and repair within the app’s spiritual framework.','divine_judgment':'Teachings about divine accountability are retained as theological context; this engine does not issue individual divine verdicts.'},'safe_experiment':experiment,'capability_definitions':capabilities,'capability_policy':'App capabilities are available as definitions for consequence modelling; this layer never invokes host, network, device or coercive actions.','source_records':reports,'references':REFERENCES,'particles':points,'connections':connections,'network_weights':{'method':'Explicit assessment relationships, not learned causal certainty'},'selected_phases':[1],'scope':'Local hypothesis, consequence and finite-model analysis. Effects on beings remain visible beside systemic effects.'}
  with self.lock:self.sequence+=1;record.update(sequence=self.sequence,time=time.time());self.latest=record;self.history.append({'sequence':self.sequence,'question':title,'assessment':assessment['assessment']['category'],'states_tested':experiment['assignments_projected']})
  c.bus.publish({'origin':'ethical-projection','target':'all','kind':'stage-output','payload':{'sequence':self.sequence,'assessment_category':assessment['assessment']['category'],'model_states_tested':experiment['assignments_projected'],'affected_groups':len(BEINGS),'provenance':'safe-conditional-ethical-projection','stochastic':False,'predefined_text':True}})
  return copy.deepcopy(record)
 def tick(self,c):
  if time.monotonic()<self.next_at:return
  self.next_at=time.monotonic()+20
  if self.research and time.monotonic()>=self.next_research:
   topics=['moral responsibility coercion harm restorative justice','insect welfare pain animal sentience','soil biodiversity microorganisms ecosystem services','biodiversity loss economic incentives land use','animal welfare human conflict resource scarcity']
   self.research.request(topics[self.sequence%len(topics)]);self.next_research=time.monotonic()+900
  self.consider(c,{'question':c.goal or 'Accountability, suffering and repair across affected beings'})
 def view(self):
  with self.lock:return {**copy.deepcopy(self.latest),'recent':list(self.history),'references':REFERENCES}
